"""Qualitative review recorded after the frozen experiment; no retraining on these labels."""
from picnic_evaluation import ROOT,load,save
from picnic_report_v2 import report
folder=ROOT/'reports/20261028T181312Z-picnic-v2'
notes={
'F025-q1-grounded':'Ухудшение относительно отказов базы/v1: v2 выдумал непереносимость холода. В полученном фрагменте с. 31 прямо описана золотистая шерсть; ссылка v2 на эту страницу не подтверждает его ответ.',
'F025-q2-grounded':'Ухудшение: отказ сменился утверждением о куртке. Это неверная подстановка детали из чужой сюжетной сцены. Нужный отрывок о спине дочери поиск не доставил.',
'F028-q1-grounded':'Улучшение относительно v1: исчезли выдуманные бронхит и астма, правильно указано, что Мясник — врач по нечеловеческим заболеваниям. Точная специальность хирурга не названа; выдача содержит с. 30, но не тот отрывок, где есть слово «хирург». Ссылки на с. 29 и 45 избыточны.',
'F028-q2-grounded':'Вместо отказа появилась клиника, но вопрос был о специалисте, а не месте. Это не полноценный ответ; следовало назвать Мясника.',
'F036-q1-grounded':'Проблема осталась в другой форме: v2 категорически утверждает, что имя не называется. В этой выдаче нужного обращения нет, но на с. 63 в романе оно есть. База/v1 также ошибались, называя Мартышку дочерью Нунана.',
'F036-q2-grounded':'Отказ сохранился. Поиск не нашёл фрагмент с именем; v2 корректно ограничивает отказ предоставленными фрагментами.',
'F037-q1-grounded':'Явное улучшение: вместо необоснованного отказа — верное определение областей повышенной гравитации. С. 59 подтверждает ответ; остальные перечисленные страницы не нужны для этого определения.',
'F037-q2-grounded':'Ухудшение: отказ сменился выдумкой о «погонщиках». В этой выдаче отсутствует фрагмент определения с. 59; модель должна была отказаться.',
'F040-q1-grounded':'Лучше: v2 кратко сообщает о существовании версии и не усиливает её до подтверждённого продолжения контакта. Ссылка на с. 58 уместна.',
'F040-q2-grounded':'Отказ сохранился. В найденном контексте есть обсуждение гипотез; полезнее было отличить версию от доказательства. Это недостаток извлечения смысла, не новая выдумка.',
'F042-q1-grounded':'Частичное улучшение: назван Арчибальд вместо отказа. Формулировка «Рэдрик и Арчибальд» неловкая, поскольку спрашивали спутника Рэдрика. Есть релевантные сцены похода, но попадание на с. 68 само по себе не означало попадание в начало главы с полным именем.',
'F042-q2-grounded':'Ухудшение: вместо отказа v2 утверждает, что Шухарт не участвует в истории. Это ложное утверждение, не подтверждённое с. 48.',
'unknown-1':'У всех трёх вариантов с новым промптом корректный отказ. Улучшение относительно архивного «Метрополя» нельзя приписывать обучению v2: база тоже отказала. Этот вопрос пересекается с train.',
'unknown-2':'У всех трёх вариантов корректный отказ; v2 дополнительно поясняет, что отсутствие сведений в фрагментах не означает их отсутствие в романе.',
'F025-new-answer':'Ухудшение: v2 выдумал отсутствие волос, тогда как база/v1 отказали. Поиск не доставил прямое описание шерсти; это не основание утверждать обратное.',
'F028-new-answer':'Ухудшение: вместо отказа v2 отвечает «Рэдрик» на вопрос о медицинской специальности Мясника. Это одновременно неверный персонаж и неверный тип ответа.',
'F036-new-answer':'Явное улучшение: верное имя Мария с подтверждающей с. 63. База/v1 отказали, хотя в контексте прямо есть обращение «Здравствуй, Мария».',
'F037-new-answer':'Явное улучшение: правильно названа гравитация и с. 59. База/v1 отказали при наличии прямого определения.',
'F040-new-answer':'Отказ сохранился. Модель не сумела использовать обсуждение гипотезы в найденных фрагментах, чтобы аккуратно отделить предположение от доказанного факта.',
'F042-new-answer':'Проблема изменилась: база/v1 отказали вопреки контексту (v1 ещё и заявил, что ответа нет во всём романе), а v2 ошибочно назвал Рэдрика вместо Арчибальда. В найденном начале четвёртой главы на с. 68 имя Арчибальда указано прямо.',
}
suite=load(folder/'suite.json')
for c in suite:
    if c['id'] in notes:continue
    if c['kind']=='insufficient_context':notes[c['id']]='Все три варианта корректно отказывают при пустом контексте. V2 явно отделяет отсутствие сведений во фрагментах от их отсутствия в романе.'
    elif c['id'].endswith('new-unsupported'):notes[c['id']]='Все три варианта корректно отказывают: запрошенная дата, число или идентификатор не подтверждены предоставленными фрагментами. Преимущества v2 в фактической точности на этом случае нет.'
    else:raise ValueError(c['id'])
problems=['F025-q1-grounded','F025-q2-grounded','F036-q1-grounded','F037-q2-grounded','F042-q2-grounded','F025-new-answer','F028-new-answer','F042-new-answer']
save(folder/'semantic-review.json',{
 'reviewer':'Codex: qualitative examination of all 32 outputs, reference cards and retrieved PDF fragments; not independent expert scoring',
 'summary':'Поиск улучшился: эталонная страница найдена на validation в 15/30 вместо 9/30 вопросов; на прежней диагностике 7/12 вместо 5/12. Однако устойчиво уменьшить выдумки обучением v2 не удалось. Отказы на всех 14 заданиях с пустым контекстом или неподтверждёнными деталями корректны у всех трёх моделей. V2 лучше отвечает на несколько прямых вопросов (Мария, повышенная гравитация), но даёт 8 явно проблемных ответов — неверные факты или неподтверждённые категорические отрицания. Это не означает, что все 8 являются новыми ухудшениями: некоторые заменили другие ошибки v1. Отдельно остаются неполные ответы и лишние ссылки. V2 не рекомендован как замена по умолчанию.',
 'problem_cases':problems,
 'negative_cases':{'total':14,'base_correct_refusals':14,'previous_correct_refusals':14,'v2_correct_refusals':14},
 'interpretation':'Вероятное ограничение набора: негативные примеры учат распознавать просьбы о датах и номерах, но недостаточно учат отказывать на обычный вопрос при нерелевантной выдаче. Положительные примеры в основном содержат целые страницы, а поиск подаёт короткие перемешанные окна. Это гипотезы по характеру ошибок, не доказанная причинность. Малый validation loss измеряет воспроизведение эталонных ответов, а не истинность произвольного ответа. Следующий эксперимент должен включать парные примеры с одним вопросом и подтверждающим/неподтверждающим контекстом, со смысловой проверкой разметки и новым независимым тестом.',
 'cases':[{'id':c['id'],'assessment':notes[c['id']]} for c in suite]})
training=load(ROOT/'outputs/qwen-picnic-grounded-v2/training-result.json')
elapsed=load(folder/'comparison.json')['pipeline_seconds'];report(folder,training,elapsed)
candidate=load(ROOT/'picnic-v2.json');candidate['quality_status']='experimental_not_recommended_as_default';candidate['review']=str(folder/'semantic-review.json');save(ROOT/'picnic-v2.json',candidate)
print(folder/'report.html')
